@Service
public class WebSocketBroadcaster {
    private final RedisTemplate<String, String> redisTemplate;
    private final SimpMessagingTemplate messagingTemplate;

    public void publishToAll(String message) {
        // Publish to Redis channel so all nodes receive the event
        redisTemplate.convertAndSend("websocket-broadcast", message);
    }

    // This method is triggered by the Redis MessageListener
    public void onMessage(String message) {
        // Broadcast to local clients connected to THIS instance
        messagingTemplate.convertAndSend("/topic/updates", message);
    }
}
